// src/components/PatientQueue.js

import React, { useState } from 'react';

import { Link } from 'react-router-dom';

import './PatientQueue.css';



const PatientQueue = () => {

  // Mock patient data (unchanged)

  const [patients, setPatients] = useState([

    {

      id: 'P001',

      age: 65,

      sex: 'M',

      chief_complaint: 'Chest pain',

      arrival_time: '09:15',

      triage_level: 2,

      wait_time: 30,

      vital_signs: { sbp: 160, hr: 92, rr: 22 }

    },

    {

      id: 'P002',

      age: 27,

      sex: 'F',

      chief_complaint: 'Abdominal pain',

      arrival_time: '09:32',

      triage_level: 3,

      wait_time: 13,

      vital_signs: { sbp: 125, hr: 88, rr: 18 }

    },

    {

      id: 'P003',

      age: 8,

      sex: 'M',

      chief_complaint: 'Fever, cough',

      arrival_time: '09:15',

      triage_level: 4,

      wait_time: 30,

      vital_signs: { sbp: 110, hr: 100, rr: 22 }

    },

    {

      id: 'P004',

      age: 42,

      sex: 'F',

      chief_complaint: 'Sprained ankle',

      arrival_time: '09:05',

      triage_level: 4,

      wait_time: 40,

      vital_signs: { sbp: 128, hr: 76, rr: 16 }

    },

    {

      id: 'P005',

      age: 18,

      sex: 'F',

      chief_complaint: 'Allergic reaction',

      arrival_time: '09:48',

      triage_level: 3,

      wait_time: 0,

      vital_signs: { sbp: 115, hr: 110, rr: 20 }

    }

  ]);

  

  // Filter states

  const [filter, setFilter] = useState('all');

  

  // Filtered patients

  const filteredPatients = filter === 'all' 

    ? patients 

    : patients.filter(p => p.triage_level === parseInt(filter));

  

  // Sort patients by triage level and then by wait time

  const sortedPatients = [...filteredPatients].sort((a, b) => {

    if (a.triage_level !== b.triage_level) {

      return a.triage_level - b.triage_level;

    }

    return b.wait_time - a.wait_time;

  });

  

  // Calculate stats

  const totalWaiting = patients.length;

  const averageWait = Math.round(patients.reduce((sum, p) => sum + p.wait_time, 0) / patients.length);

  

  return (

    <div className="queue-container">

      <div className="queue-header">

        <div className="queue-header-left">

          <h1>Patient Queue</h1>

          <div className="queue-stats">

            <div className="stat-pill">

              <span className="stat-label">Total Waiting:</span>

              <span className="stat-value">{totalWaiting}</span>

            </div>

            <div className="stat-pill">

              <span className="stat-label">Average Wait:</span>

              <span className="stat-value">{averageWait} min</span>

            </div>

          </div>

        </div>

        <Link to="/patient/new" className="action-button primary">

          Add New Patient

        </Link>

      </div>

      

      <div className="queue-filters">

        <button 

          className={`filter-button ${filter === 'all' ? 'active' : ''}`}

          onClick={() => setFilter('all')}

        >

          All

        </button>

        <button 

          className={`filter-button level-1 ${filter === '1' ? 'active' : ''}`}

          onClick={() => setFilter('1')}

        >

          Level 1

        </button>

        <button 

          className={`filter-button level-2 ${filter === '2' ? 'active' : ''}`}

          onClick={() => setFilter('2')}

        >

          Level 2

        </button>

        <button 

          className={`filter-button level-3 ${filter === '3' ? 'active' : ''}`}

          onClick={() => setFilter('3')}

        >

          Level 3

        </button>

        <button 

          className={`filter-button level-4 ${filter === '4' ? 'active' : ''}`}

          onClick={() => setFilter('4')}

        >

          Level 4

        </button>

        <button 

          className={`filter-button level-5 ${filter === '5' ? 'active' : ''}`}

          onClick={() => setFilter('5')}

        >

          Level 5

        </button>

      </div>

      

      <div className="patient-list">

        {sortedPatients.map(patient => (

          <div key={patient.id} className={`patient-card triage-${patient.triage_level}`}>

            <div className="patient-header">

              <div className="patient-id">{patient.id}</div>

              <div className="patient-triage">

                Level {patient.triage_level}

              </div>

            </div>

            <div className="patient-body">

              <div className="patient-info">

                <div className="patient-demographics">

                  {patient.age} y/o {patient.sex}

                </div>

                <div className="patient-complaint">

                  {patient.chief_complaint}

                </div>

              </div>

              <div className="patient-vitals">

                <div className="vital-sign">

                  <span className="vital-label">BP:</span>

                  <span className="vital-value">{patient.vital_signs.sbp}/{patient.vital_signs.sbp - 40}</span>

                </div>

                <div className="vital-sign">

                  <span className="vital-label">HR:</span>

                  <span className="vital-value">{patient.vital_signs.hr}</span>

                </div>

                <div className="vital-sign">

                  <span className="vital-label">RR:</span>

                  <span className="vital-value">{patient.vital_signs.rr}</span>

                </div>

              </div>

            </div>

            <div className="patient-footer">

              <div className="wait-time">

                Waiting: <strong>{patient.wait_time}</strong> min

              </div>

              <div className="arrival-time">

                Arrived: {patient.arrival_time}

              </div>

              <Link to={`/triage/${patient.id}`} className="view-details-link">

                View Details

              </Link>

            </div>

          </div>

        ))}

        

        {sortedPatients.length === 0 && (

          <div className="no-patients-message">

            No patients match the selected filter.

          </div>

        )}

      </div>

    </div>

  );

};



export default PatientQueue;
